/* ---------- end-of-section quiz (MC and LQ decks) ----------
   Deck: header (tag, title, export) > lede > LO pills > card > Prev / Next.
   Card: LO band, then one question: paper id + "also LO" meta, the scan,
   A-D answer tiles, verdict. Only the current question is in the flow. */

.section-dse {
  --quiz-line: #cddcd6;
  margin: 1.6rem 0 0;
  padding: 1.15rem 1.2rem 1.25rem;
  background: #eef5f2;
  border: 1px solid var(--quiz-line);
  border-left: 4px solid var(--accent);
  border-radius: 8px;
}

.section-dse + .section-dse { margin-top: 1.1rem; }

.section-dse > header {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  margin: 0 0 0.3rem;
  flex-wrap: wrap;
}

.section-dse > header h2 {
  font-family: var(--sans);
  font-size: 0.84rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent-deep);
  margin: 0;
}

.section-dse > header .sec-num {
  display: inline-block;
  min-width: 0;
  margin: 0;
  padding: 0.12rem 0.45rem;
  font-family: var(--sans);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  line-height: 1.35;
  color: var(--mark);
  background: var(--mark-soft);
  border: 1px solid #ead9b6;
  border-radius: 4px;
}

.section-dse > p {
  margin: 0 0 0.9rem;
  color: var(--muted);
  font-size: 0.91rem;
}

.quiz-export {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.76rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--accent-deep);
  border: 1px solid #b6cbc5;
  border-radius: 4px;
  padding: 0.28rem 0.6rem;
  background: #fff;
  transition: background-color 120ms ease, border-color 120ms ease;
}

.quiz-export::before {
  content: "↓";
  font-size: 0.9em;
  color: var(--accent);
}

.quiz-export:hover { background: var(--accent-soft); border-color: var(--accent); }

/* LO pills: which learning objective the current question tests */

.quiz-lo-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem 0.6rem;
  margin: 0 0 0.6rem;
}

.quiz-lo-bar-label {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

.quiz-los {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
}

.quiz-lo-tab {
  min-width: 3.2rem;
  padding: 0.26rem 0.7rem;
  font-size: 0.8rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  background: #fff;
  color: var(--accent-deep);
  border: 1px solid #b6cbc5;
  border-radius: 999px;
  transition: background-color 120ms ease, border-color 120ms ease, color 120ms ease;
}

.quiz-lo-tab:hover { border-color: var(--accent); background: var(--accent-soft); }

.quiz-lo-tab.is-current,
.quiz-lo-tab[aria-selected="true"] {
  background: var(--accent-deep);
  color: #f2ede2;
  border-color: var(--accent-deep);
