.quiz-lo-tab:focus-visible,
.quiz-letter:focus-visible,
.quiz-export:focus-visible,
.quiz-nav button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* The card */

.quiz-slides {
  min-height: 8rem;
  overflow: hidden;
  background: var(--panel);
  border: 1px solid var(--quiz-line);
  border-radius: 8px;
  padding: 0;
}

.quiz-lo {
  display: flex;
  align-items: baseline;
  gap: 0.55rem;
  margin: 0;
  padding: 0.6rem 0.95rem;
  background: var(--accent-soft);
  border-bottom: 1px solid var(--quiz-line);
  color: var(--ink);
  font-size: 0.95rem;
  font-weight: 600;
  line-height: 1.35;
}

.quiz-lo-num {
  flex: 0 0 auto;
  padding: 0.08rem 0.45rem;
  font-size: 0.74rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  font-variant-numeric: tabular-nums;
  color: #f2ede2;
  background: var(--accent-deep);
  border-radius: 4px;
}

.quiz-lo-text::first-letter { text-transform: uppercase; }

.quiz-slide { display: none; }

.quiz-slide.is-current {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas:
    "id also"
    "paper paper"
    "answer answer"
    "verdict verdict";
  align-items: center;
  gap: 0.65rem 0.75rem;
  padding: 0.75rem 0.95rem 1rem;
}

.quiz-slide > h3,
.quiz-slide > p { display: none; }

.quiz-slide .dse-paper { display: contents; }

.quiz-slide .dse-paper figcaption {
  grid-area: id;
  justify-self: start;
  margin: 0;
  padding: 0.14rem 0.5rem;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.03em;
  font-variant-numeric: tabular-nums;
  color: var(--accent-deep);
  background: #fff;
  border: 1px solid var(--quiz-line);
  border-radius: 4px;
}

.quiz-slide > p.quiz-also {
  grid-area: also;
  display: block;
  margin: 0;
  color: var(--muted);
  font-size: 0.8rem;
  font-variant-numeric: tabular-nums;
}

.quiz-slide .dse-paper img {
  grid-area: paper;
  display: block;
  width: 100%;
  height: auto;
  background: #fff;
  border: 1px solid var(--rule-soft);
  border-radius: 4px;
}

.quiz-slide .dse-paper .dse-slot { grid-area: paper; }

/* A B C D tiles */

.quiz-choices {
  grid-area: answer;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.5rem;
  width: 100%;
  max-width: 24rem;
  margin: 0.15rem 0 0;
}

.quiz-letter {
  min-height: 3rem;
  padding: 0.5rem 0;
  font-weight: 800;
  font-size: 1.1rem;
  letter-spacing: 0.02em;
  color: var(--accent-deep);
  background: #fff;
  border: 1.5px solid #c8d5d0;
  border-radius: 6px;
  transition: background-color 120ms ease, border-color 120ms ease, color 120ms ease, transform 120ms ease;
}

.quiz-letter:hover:not(:disabled) {
  border-color: var(--accent);
  background: var(--accent-soft);
}

.quiz-letter:active:not(:disabled) { transform: translateY(1px); }

.quiz-letter.is-picked {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.quiz-letter:disabled {
  cursor: default;
  color: #9aa3ad;
  border-color: var(--rule-soft);
  background: #fbf9f4;
}

.quiz-letter.correct,
.quiz-letter.correct:disabled {
  background: var(--ok-soft);
  color: var(--ok);
  border-color: var(--ok);
}

.quiz-letter.wrong,
.quiz-letter.wrong:disabled {
  background: var(--bad-soft);
  color: var(--bad);
  border-color: var(--bad);
}

/* Verdict under the tiles */

.quiz-slide > p.quiz-pct {
  grid-area: verdict;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.2rem 0.75rem;
  margin: 0;
  padding: 0.5rem 0.75rem;
  border-radius: 6px;
  border-left: 3px solid currentColor;
  font-size: 0.92rem;
  line-height: 1.4;
}

.quiz-slide > p.quiz-pct[hidden] { display: none; }

.quiz-pct.is-right { background: var(--ok-soft); color: var(--ok); }
.quiz-pct.is-wrong { background: var(--bad-soft); color: var(--bad); }

.quiz-verdict { font-weight: 700; }

.quiz-stat {
  color: var(--muted);
  font-size: 0.86rem;
  font-variant-numeric: tabular-nums;
}

/* Prev / Next under the card */

.quiz-nav {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.75rem;
  margin: 0.8rem 0 0;
}

.quiz-nav [data-quiz-prev],
.quiz-nav [data-quiz-next] {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  min-width: 6.4rem;
  padding: 0.5rem 0.95rem;
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--accent-deep);
  background: #fff;
  border: 1px solid #b6cbc5;
  border-radius: 6px;
  transition: background-color 120ms ease, border-color 120ms ease, color 120ms ease;
}

.quiz-nav [data-quiz-prev] { justify-content: flex-start; }
.quiz-nav [data-quiz-next] { justify-content: flex-end; }

.quiz-nav [data-quiz-prev]::before { content: "←"; color: var(--accent); }
.quiz-nav [data-quiz-next]::after { content: "→"; color: var(--accent); }

.quiz-nav [data-quiz-prev]:hover,
.quiz-nav [data-quiz-next]:hover {
  background: var(--accent-deep);
  border-color: var(--accent-deep);
  color: #f2ede2;
}

.quiz-nav [data-quiz-prev]:hover::before,
.quiz-nav [data-quiz-next]:hover::after { color: #f2ede2; }

.quiz-progress {
  display: grid;
  justify-items: center;
  gap: 0.35rem;
  min-width: 0;
}

.quiz-status {
  margin: 0;
  text-align: center;
  color: var(--muted);
  font-size: 0.86rem;
  font-variant-numeric: tabular-nums;
  font-weight: 600;
}

.quiz-dots {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.3rem;
}

.quiz-dots[hidden] { display: none; }

.quiz-dot {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: #fff;
  border: 1.5px solid #b6cbc5;
  transition: transform 120ms ease, background-color 120ms ease;
}

.quiz-dot.is-current {
  transform: scale(1.3);
  border-color: var(--accent-deep);
  background: var(--accent-deep);
}

.quiz-dot.is-right { border-color: var(--ok); background: var(--ok); }
.quiz-dot.is-wrong { border-color: var(--bad); background: var(--bad); }

.lo-block, .check, .section-dse { padding-left: 0.8rem; padding-right: 0.8rem; }

.quiz-lo { padding: 0.5rem 0.75rem; font-size: 0.9rem; }
.quiz-slide.is-current { padding: 0.65rem 0.7rem 0.85rem; gap: 0.55rem 0.6rem; }
.quiz-choices { max-width: none; }
.quiz-nav { gap: 0.5rem; }

.quiz-nav [data-quiz-prev],
.quiz-nav [data-quiz-next] { min-width: 0; padding: 0.45rem 0.7rem; }

.quiz-status { font-size: 0.8rem; }

