function dist2d(p,s){const ax=s.a.x,az=s.a.z,bx=s.b.x,bz=s.b.z;const dx=bx-ax,dz=bz-az;const L2=dx*dx+dz*dz;let t=((p.x-ax)*dx+(p.z-az)*dz)/L2;t=Math.max(0,Math.min(1,t));const cx=ax+t*dx,cz=az+t*dz;return Math.hypot(p.x-cx,p.z-cz)}
